"""Component p-82af68dd@100000/layers.15.mlp.down_proj:2066 (layer 15 MLP output).

What it does, in plain terms: most of this component's activation is diffuse. It is about 0
on average, with spread about 0.4 that no simple token pattern explains. The clear pattern is
at control-flow keywords in code. Inside code (after a line break, indentation, or a closing
brace):
  - `else` and `try` push the activation strongly negative (about -2 to -2.5 on the keyword);
  - the punctuation that opens the block just after them (`:`, ` {`, or a newline) pushes it
    more negative still (about -4);
  - the two or three tokens after that fade out;
  - `return` gives a smaller dip (about -1).
The same words in prose ("try to", "try me") do nothing, so they get the baseline.

This program predicts those dips, the baseline elsewhere. It captures only a small share of the
variance: the spread of the activation everywhere else is not modelled.
"""

READS = ()

BASELINE = 0.04  # the component's mean activation
OPENERS = ("else", "try")  # keywords that open a code block
CODE_KEYWORD = -2.0  # `else` / `try` in code
BLOCK_START = -4.0  # the `:`, `{` or newline right after such a keyword
AFTER_OPENER = {2: -0.5, 3: -0.3, 4: -0.15}  # tokens 2 to 4 after the keyword
RETURN_IN_CODE = -1.0  # `return` in code


def in_code(prev):
    # Code layout just before a token: a line break, indentation, or a closing brace or semicolon.
    return prev.strip() == "" or "\n" in prev or prev.strip() in ("}", ";", ")")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        code_block, since = False, 99  # a new document resets the state
    else:
        code_block, since = carry[1], min(carry[2] + 1, 99)  # tokens since the keyword
    value = BASELINE
    if word in OPENERS:
        code_block, since = in_code(prev), 0
        if code_block:
            value = CODE_KEYWORD
    elif word == "return":
        if in_code(prev):
            value = RETURN_IN_CODE
    elif code_block and since == 1 and (":" in token or "{" in token or "\n" in token):
        value = BLOCK_START
    elif code_block:
        value = AFTER_OPENER.get(since, BASELINE)
    return (doc, code_block, since), value

"""Layer 15 MLP down_proj, component 2073: a "conditional logic in code" detector.

What it responds to: the words that open a branch or a test. Its strongest
response is to `if` that starts a statement inside indented code (`\tif`, or
` if` after indentation), most of all in Go/C-style error checks such as
`err := f()` followed by `if err != nil`. Weaker responses come from `if` in
English prose, from `err`, comparison operators (`==`, `!=`, `<=`, `||`),
`catch`/`except`/`elif`/`else`, `nil`/`NULL`, and conditional words in other
languages (如果, если, なければ). Most other tokens are near zero, and the
component's sign is mixed on punctuation and indentation, which this program
ignores.

How the program predicts it: each token gets a value from its class.
`if` gets a value that grows with how code-like the 16 tokens before it are,
and more when the token opens a line (follows indentation). `if` after a recent
`err` gets a bonus. The other classes get fixed values.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

WINDOW = 16
CODE_MARKS = set("{};()[]<>=&|:\t\n")
IF_WORDS = {" if", "if", " If", "If"}
TAB_IF = "\tif"
ERR_WORDS = {" err", "\terr"}
COMPARE_WORDS = {" ==", " !=", " ===", " !==", " <=", " >=", " ||", " &&", " <", " >"}
BRANCH_WORDS = {" else", " catch", " except", " elif", "else", "catch", "except"}
NULL_WORDS = {" nil", " NULL", " null", " None"}
CONDITION_WORDS = {"如果", "若是", "なければ", "ければ", "если", " если", " Если"}


def looks_like_code(text: str) -> bool:
    return any(ch in CODE_MARKS for ch in text)


def opens_line(text: str) -> bool:
    return text.strip() == "" or "\n" in text


def step(carry, prefix, upstream: Mapping):
    token = prefix.token_strings[-1]
    t = prefix.position
    doc = prefix.document_ids[-1]
    earlier = [
        i for i in range(max(0, t - WINDOW), t) if prefix.document_ids[i] == doc
    ]
    code_fraction = sum(looks_like_code(prefix.token_strings[i]) for i in earlier) / WINDOW

    if token in IF_WORDS:
        after_indent = t > 0 and opens_line(prefix.token_strings[t - 1])
        if after_indent:
            value = 2.7 + 8.9 * code_fraction
        else:
            value = 1.0 + 2.9 * code_fraction
        if any(prefix.token_strings[i] in ERR_WORDS for i in earlier):
            value += 5.0
    elif token == TAB_IF:
        value = 8.0
    elif token in ERR_WORDS:
        value = 3.5
    elif token in COMPARE_WORDS or token in BRANCH_WORDS:
        value = 1.0
    elif token in NULL_WORDS:
        value = 0.5
    elif token in CONDITION_WORDS:
        value = 2.0
    else:
        value = 0.0
    return carry, value

"""Novelty and first-time detector: a readable stand-in for component 2074 of layer 15's MLP.

The component fires on words that mark something as happening for the first time, as never
before, or as unexpected: "his first", "for the first time", "had never", "never before",
"unprecedented", "unusual", "surprised". It is near zero on most tokens.
"""

READS = ()

POSSESSIVE = {"his", "her", "their", "my", "our", "your", "its", "'s", "’s"}
HAVE = {"had", "have", "has", "'ve", "’ve", "i", "we", "would"}
NOVEL = {"unprecedented": 7.0, "unusual": 8.0, "debut": 4.0, "surprise": 4.0,
         "surprised": 4.0, "unexpected": 4.0, "anticipated": 2.0, "previously": 3.0,
         "novel": 2.0, "ever": 2.0, "unique": 1.0, "firsts": 3.0, "initially": 2.0}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    tok = _word(prefix.token_strings[-1])
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""
    else:
        prev = _word(prefix.token_strings[-2])
    if tok == "time" and prev == "first":
        return carry, 15.0
    if tok == "before" and prev == "never":
        return carry, 15.0
    if tok == "first":
        return carry, 9.0 if prev in POSSESSIVE else 1.5
    if tok == "never":
        return carry, 6.0 if prev in HAVE else 1.5
    return carry, NOVEL.get(tok, 0.0)

"""Layer 15 MLP, down_proj component 2076.

This component reads the MLP's hidden activations along one direction (mostly
hidden unit 2076) and writes a small signal into the residual stream. Its
activation is small and noisy, and almost none of it is explained by the token
alone. The one readable pattern is a gender axis:

- male person words ("male", "boys", "sons", "men", "father", "dad") push it
  clearly negative;
- male pronouns ("he", "him", "his") push it slightly negative;
- female person words ("female", "girl", "woman", "women", "mother") push it
  weakly positive.

Every other token is predicted as 0. This program scores almost nothing on
variance explained; the lexicon is the part a reader can follow.
"""

READS = ()

MALE_NOUNS = {
    "male", "males", "boy", "boys", "son", "sons",
    "father", "fathers", "dad", "dads", "men",
}
MALE_PRONOUNS = {"he", "him", "his", "himself"}
FEMALE_NOUNS = {
    "female", "females", "girl", "girls", "woman", "women",
    "mother", "wife", "lady", "ladies",
}


def step(carry, prefix, upstream):
    """The activation at this position, from the word the newest token spells."""
    word = prefix.token_strings[-1].strip().lower()
    if word in MALE_NOUNS:
        value = -1.0
    elif word in MALE_PRONOUNS:
        value = -0.15
    elif word in FEMALE_NOUNS:
        value = 0.15
    else:
        value = 0.0
    return carry, value

"""Hyphens that join a word-piece to what follows, and a few joiner particles.

Component p-82af68dd@100000/layers.15.mlp.down_proj:2083 writes a large positive
signal when a token glues a word-part onto the piece that follows it inside one term.
Its strongest case is a bare hyphen right after a letter ("anti-", "micro-", "ethyl-",
"co-", "multi-"), largest after a Cyrillic word, and weaker after a digit or a
punctuation mark. Weaker still: the comma inside a number ("19,000", strongest after a
"$"), and the Chinese/Japanese particles 的 地 の 之. The signal is damped where the
hyphen sits in code (identifiers, brackets, operators), and it is slightly negative on
the coordinators 和 and 与 ("and"). Everything else predicts about zero.

The program reads only the text up to the position it predicts.
"""

import re

READS = ()

DASHES = set("-‐‑–—")  # ASCII hyphen, Unicode hyphens and dashes
CODE = re.compile(r"[{}()\[\];=_<>\\$/]")
PARTICLES = {"的": 2.0, "地": 2.0, "の": 1.2, "之": 1.2}
COORDINATORS = {"和": -1.2, "与": -1.2}
COMMAS = {",", "，", "、"}
WINDOW = 30  # recent tokens scanned for code


def _is_hyphen(tok):
    """A short token that contains a dash and is not glued to a space, an arrow or "--"."""
    return (
        0 < len(tok) <= 3
        and not tok.startswith(" ")
        and any(ch in DASHES for ch in tok)
        and "--" not in tok
        and ">" not in tok
    )


def _hyphen_value(prev):
    """How strongly a hyphen fires, given the token just before it."""
    if not prev or prev[-1].isspace():
        return 0.0
    c = prev[-1]
    if c.isascii() and c.isalpha():
        return 2.3
    if "Ѐ" <= c <= "ӿ":
        return 6.0
    if c.isdigit():
        return 1.0
    if "一" <= c <= "鿿":
        return 0.45
    return 0.9


def _comma_value(before):
    """A comma after a number: strongest after a 1-3 digit number that follows "$"
    (like "$2,500"); weak after a longer digit run like "1000,"."""
    run = 0
    while run < len(before) and len(before[-1 - run]) == 1 and before[-1 - run].isdigit():
        run += 1
    if run == 0 or run > 3:
        return 0.1
    preceded_by_dollar = len(before) > run and before[-run - 1].endswith("$")
    return 4.0 if preceded_by_dollar else 0.8


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix.token_strings) > 1 and (
        prefix.document_ids[-2] == prefix.document_ids[-1]
    )
    prev = prefix.token_strings[-2] if same_doc else ""

    recent = prefix.token_strings[-WINDOW - 1 : -1]
    code = sum(1 for s in recent if CODE.search(s))
    damp = max(0.2, 1.0 - code / 6.0)  # hyphens inside code fire weakly

    if _is_hyphen(tok):
        value = _hyphen_value(prev) * damp
    elif tok in PARTICLES:
        value = PARTICLES[tok]
    elif tok in COORDINATORS:
        value = COORDINATORS[tok]
    elif tok in COMMAS and prev.isdigit():
        value = _comma_value(prefix.token_strings[:-1])
    else:
        value = 0.0
    return carry, float(value)

"""MLP unit 2093 of layer 15 (the down_proj component 2093), read as a code-syntax detector.

Plain-terms summary. Almost all of this unit's activity is small and diffuse, so no
short rule captures it. Its largest responses are in C-style `for` and `while` loops,
as the loop header is written token by token:

  * positive on the loop keyword when it starts a line ("for", "while"), on the "("
    after it, on a type word inside the header ("int"), and on "=" (as in "int i = 0");
  * negative on the other header tokens such as the loop variable ("i", "j", "n"),
    most strongly on the ")" that closes the header and on the "{" that opens the body.

Everywhere else the program predicts 0. Each value is the average activation measured
on a sample of training code for that case, so the program is a per-case mean, not a fit.
"""

READS = ()

LOOP_WORDS = {"for", "while"}
TYPE_WORDS = {"int", "long", "auto", "let", "var", "size_t"}
LOOP_VARS = {"i", "j", "k", "n", "x", "idx"}


def step(carry, prefix, upstream):
    # The state is (mode, depth): mode 0 = outside a loop header, 1 = just after the
    # keyword (expecting "("), 2 = inside the header, 3 = header closed (expecting "{").
    if len(prefix.token_strings) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        carry = None
    mode, depth = carry if carry is not None else (0, 0)
    s = prefix.token_strings[-1]
    st = s.strip()
    value = 0.0
    if mode == 0:
        if st in LOOP_WORDS:
            line_start = len(prefix.token_strings) == 1 or prefix.token_strings[-2].strip() == ""
            value = 1.5 if line_start else 0.0
            mode, depth = 1, 0
        elif "{" in s and "\n" in s:
            value = -0.9
    elif mode == 1:
        if "(" in s:
            value, mode, depth = 1.4, 2, s.count("(") - s.count(")")
        else:
            mode = 0
    elif mode == 2:
        depth += s.count("(") - s.count(")")
        if ")" in s and depth <= 0:
            value = -5.0 if "{" in s else -2.3
            mode = 0 if "{" in s else 3
        elif st in TYPE_WORDS:
            value = 3.5
        elif st == "=":
            value = 1.8
        elif st in LOOP_VARS:
            value = -1.5
        else:
            value = -0.6
    elif mode == 3:
        if "{" in s:
            value = -3.3 if "\n" in s else -1.6
        mode = 0
    return (mode, depth), value

"""Layer 15 MLP hidden unit 2100 (down_proj component 2100), as a word-class rule.

The component is essentially one MLP neuron. Its activation is noisy and
context-dependent, and no simple rule tracks it closely. What the rules below capture is
its one clear pattern: it is most positive on a main verb (or past-participle) that comes
right after a subject pronoun or an auxiliary ("we [were] used", "I [thought]",
"has [been]"). It is mildly positive on other verbs, and mildly negative on function
words (auxiliaries, pronouns, prepositions, determiners).

Each cell's value is the mean activation of that word class on training text.
"""

from functools import lru_cache

import wordnet

READS = ()

SUBJECT_PRONOUNS = {"i", "we", "you", "they", "he", "she", "it"}
AUXILIARIES = {
    "is", "are", "was", "were", "be", "been", "being", "am", "have", "has", "had",
    "do", "does", "did", "will", "would", "can", "could", "should", "may", "might",
    "must", "not",
}
PREPOSITIONS = {
    "in", "on", "at", "by", "of", "for", "to", "from", "with", "into", "about",
    "over", "under", "after", "before", "between", "through", "during",
}
DETERMINERS = {
    "a", "an", "the", "this", "that", "these", "those", "its", "his", "her",
    "their", "our", "my", "your",
}

# Mean activation of each cell on training text.
CELL_VALUE = {
    "verb_after_subject_or_aux": 0.58,
    "other_verb": 0.11,
    "pronoun_or_aux": -0.155,
    "preposition": -0.137,
    "determiner": -0.105,
    "word_after_determiner": -0.111,
    "other_word": -0.047,
}


@lru_cache(maxsize=None)
def is_verb(word):
    """A word WordNet lists only as a verb, or an -ed form of one."""
    if not word.isalpha() or not word.isascii():
        return False
    return wordnet.parts_of_speech(word) == {"verb"} or (word.endswith("ed") and len(word) > 3)


def cell(word, previous):
    if is_verb(word):
        if previous in SUBJECT_PRONOUNS or previous in AUXILIARIES:
            return "verb_after_subject_or_aux"
        return "other_verb"
    if word in SUBJECT_PRONOUNS or word in AUXILIARIES:
        return "pronoun_or_aux"
    if word in PREPOSITIONS:
        return "preposition"
    if word in DETERMINERS:
        return "determiner"
    if previous in DETERMINERS:
        return "word_after_determiner"
    return "other_word"


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    previous = prefix.token_strings[-2].strip().lower() if len(prefix.token_ids) > 1 else ""
    return carry, CELL_VALUE[cell(word, previous)]

"""Layer 15 MLP, down_proj component 2102: a "statement in source code" detector.

What it is: the component's activation is almost entirely MLP hidden unit 2102 of
layer 15 (about 55% of its energy, correlation 0.75), scaled. Switched on, it pushes the
next-token prediction toward ';' and away from line-ending tokens such as ')\\n'.

When it is large and positive: at tokens that open or carry a statement in programming
code: the assignment '=' (strongest), 'return' and 'break', print/cout/printf, and
top-level keywords such as import, using, namespace, package. Where the surrounding
text is mostly code, these fire harder. When it is negative: the '(' that opens the
condition of if / for / while / switch, again more so in dense code. Everything else,
prose and maths included, is about 0.

The program measures "code density": the share of the previous 64 tokens of the same
document that contain a statement or block character (; { }). Values are the least-squares
fit of these class weights (see the explanation). It does not model the rare, huge
values, such as Cyrillic name fragments; those carry little of the variance.
"""

from collections import deque

READS = ()

ASSIGN = {" =", " :=", " +=", " -=", " *="}
RETURN = {" return", "\treturn", "return", " break", "\tbreak"}
PRINT = {" println", ".println", "println", " cout", "cout", " printf"}
TOP_KEYWORD = {"import", " import", "using", " using", " namespace", "namespace", "package", "use"}
COLON = {":", " :", "::"}
CONTROL = {" if", "if", " for", "for", " while", "while", " switch", "switch"}
OPEN_PAREN = {" ("}
WINDOW = 64
FULL_CODE = 0.05  # code density at which the code gate saturates


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, prev_tok = deque(maxlen=WINDOW), ""
    else:
        _, recent, prev_tok = carry

    density = sum(recent) / len(recent) if recent else 0.0
    gate = min(1.0, density / FULL_CODE)  # 0 in prose, 1 in dense code

    if tok in ASSIGN:
        value = 0.9 + 4.4 * gate
    elif tok in RETURN:
        value = 0.8 + 6.9 * gate
    elif tok in PRINT:
        value = 5.7 + 0.7 * gate
    elif tok in TOP_KEYWORD:
        value = 0.8 + 2.2 * gate
    elif tok in COLON:
        value = 1.2 + 0.2 * gate
    elif tok in OPEN_PAREN and prev_tok in CONTROL:
        value = -1.0 - 2.3 * gate
    else:
        value = 0.0

    # the code flag of this token joins the window for the next position
    recent.append(any(ch in tok for ch in ";{}"))
    return (doc, recent, tok), value

"""Operator that joins two operands (layer 15 MLP, component 2105).

In plain terms: this component is active on the token that combines two quantities or
things: the operator that sits between a left operand (a number, a variable, a closing
bracket, or a content word) and a right operand still to come. The strongest cases are the
multiplication signs ("×", "*", "·", "\\times", "\\cdot", "times"). "+" and "plus" and the
joining words "multiplied", "divided", "combined", "followed" come next, about 60% as strong.
Parenthesised operator tokens such as ")(" or ")*" are weaker, and "-" and "/" weakest.
The strength is multiplied by how well the token before the operator can end an operand:
full after a number, a variable or a closing bracket, about 40% after a function word
("the", "of", "and"), about 40% after other symbols, and near zero after a space, a newline
or an opening bracket (where the operator is a bullet, a sign or a line start).

The strengths are hand-set round numbers, shaped by a least-squares fit on 4096 training
rows (about 2 million tokens). The program explains only about 8 percent of the variance;
the component's large spikes are not captured by any short rule.
"""

import re

READS = ()

PLUS = {"+"}
TIMES = {"×", "*", "·", "\\times", "\\cdot", "times", "cdot"}
MINUS = {"-", "−", "–"}
DIVIDE = {"/", "÷"}
JOIN_WORDS = {"plus", "multiplied", "divided", "combined", "followed"}
FUNCTION_WORDS = set(
    "the a an of to in on at by for with from as is are was were be been being this that these "
    "those it its and or but if then so than there here he she they we you i my your his her "
    "their our not no do does did has have had which who what when where how about into over "
    "under between through during after before".split()
)

STRENGTH = {"plus": 3.0, "times": 5.0, "minus": 1.0, "divide": 0.5, "words": 3.0, "parens": 2.0}
GATE = {"operand": 1.0, "function": 0.4, "other": 0.4, "space": 0.05}
SCALE = 1.0


def operator_class(raw):
    """Which operator family a decoded token belongs to, or None."""
    tok = raw.strip()
    if tok in PLUS:
        return "plus"
    if tok in TIMES:
        return "times"
    if tok in MINUS:
        return "minus"
    if tok in DIVIDE:
        return "divide"
    if tok in JOIN_WORDS:
        return "words"
    if any(c in tok for c in "()") and set(tok) <= set("()*+/-") and any(c in tok for c in "*+/-"):
        return "parens"
    return None


def previous_kind(prev):
    """How well the token before the operator can end an operand."""
    s = prev.strip()
    if s == "" or prev.endswith("\n") or s in ("(", "[", "{"):
        return "space"
    if s.isdigit() or s in (")", "]", "}") or prev.endswith(")"):
        return "operand"
    if re.fullmatch(r"[A-Za-z]+", s):
        return "function" if s.lower() in FUNCTION_WORDS else "operand"
    return "other"


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    t = prefix.position
    cls = operator_class(toks[t])
    # the operator needs a left operand from the same document
    if cls is None or t == 0 or docs[t - 1] != docs[t]:
        return carry, 0.0
    value = STRENGTH[cls] * GATE[previous_kind(toks[t - 1])]
    return carry, float(SCALE * value)

"""Layer 15 MLP down_proj, component 2106: a "binary operator in a formula" detector.

The component fires on the token of a binary operator that joins two terms of a
formula: "+" most of all (e.g. "x^2 + y^2", "a*b + c", and ")+" after a bracket), then
"-" / "−" / "–", "×" / "*" / "·", and "/" / "÷". Code-style joiners ("else", "&&", "||")
also fire, weaker. Every other token is predicted as 0.

How strongly it fires depends on how mathematical the surrounding text looks: each
operator's value is scaled by the share of the previous 12 tokens (same document) that
look like maths (digits, single letters, brackets, "=", "^", "\\", or math symbols).
The same "+" can be up to about 5 times larger inside an equation than in prose or a diff.

Values are rough class means fitted on about 16k training rows (activation scale).
"""

import re

READS = ()

PLUS = {" +", "+", ")+", "+(", ")+(", " plus", "+x", "+a"}
MINUS = {" -", "-", " −", "−", " –", ")-", "-(", ")-(", "}-", " minus"}
TIMES = {" ×", "×", " *", ")*", ")*(", "*", "}*", "·", " ·", "times"}
DIVIDE = {" /", "/", ")/", ")/(", "/(", "÷", " ÷", "))/", "]/"}
CODE_JOIN = {" else", "else", "\telse", " elif", "}else", " &&", "&&", " ||", "||"}

VALUE = {}
for group, value in [(PLUS, 3.3), (MINUS, 1.0), (TIMES, 1.0), (DIVIDE, 0.8), (CODE_JOIN, 2.7)]:
    for token in group:
        VALUE[token] = value

MATHY = re.compile(r"[=^()\\{}\[\]]|\d|^\s?[A-Za-z]$|[−×÷·]")
WINDOW = 12


def step(carry, prefix, upstream):
    t = prefix.position
    base = VALUE.get(prefix.token_strings[-1], 0.0)
    if base == 0.0:
        return carry, 0.0
    doc = prefix.document_ids[-1]
    before = [
        prefix.token_strings[i]
        for i in range(max(0, t - WINDOW), t)
        if prefix.document_ids[i] == doc
    ]
    mathiness = sum(bool(MATHY.search(s)) for s in before) / max(len(before), 1)
    return carry, base * (0.3 + 1.4 * mathiness)

"""Layer 15 MLP down-projection, component 2107: a "clause-joining conjunction" detector.

What it does: this component is positive when a coordinating or contrasting word
starts a new clause right after a comma or semicolon, as in "..., and the ...",
"..., or ...", "..., but ...", "..., while ...", "..., und ...", "..., et ...".
Strongest for "or", "while", "und", "а", "et" and "and"; weaker for "but",
"yet" and for connectives such as ", however", ", though", ", as", ", so".
The same words without a preceding comma, and everything else, get 0.

Why: in the sampled activations, these clause-opening words carry almost all of
the component's large positive values (about +1.3 to +2.4 on average, versus about
0 for the same words elsewhere). Its activation everywhere else is a diffuse
+/-0.4 noise that the causal-importance estimate says the model does not use,
and no word-level rule captures it, so the program leaves it at 0.
"""

READS = ()

# Coordinators (joining two clauses) after a comma or semicolon, and their mean activation.
COORDINATORS = {
    " or": 2.4, " while": 2.1, " und": 2.3, " а": 2.2, " et": 2.0, " and": 1.8,
    " but": 1.3, " yet": 1.4, " oder": 1.0, " o": 1.1, " y": 0.8, " ou": 0.8,
    " And": 0.8, " But": 0.8, " Or": 1.0, " mais": 2.0, " sino": 2.0, " aber": 1.2,
    " pero": 1.5,
}
# Contrast and subordinating connectives after a comma: weaker.
CONNECTIVES = {
    " however": 1.0, " though": 0.8, " although": 0.7, " as": 0.8, " so": 0.5,
    " where": 0.6, " not": 0.8, " such": 0.7, " especially": 0.6, " with": 0.5,
    " then": 0.4, " than": 0.5,
}
CLAUSE_PUNCTUATION = {",", ";", "，", "；", "、"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if len(prefix.document_ids) > 1 and prefix.document_ids[-2] != prefix.document_ids[-1]:
        previous = ""  # a new document starts here: no comma before it
    if previous.strip() in CLAUSE_PUNCTUATION:
        if word in COORDINATORS:
            return carry, float(COORDINATORS[word])
        if word in CONNECTIVES:
            return carry, float(CONNECTIVES[word])
    return carry, 0.0
